@import "tailwindcss" source(none);
@source "..";
@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: "DM Sans", sans-serif;
  --font-display: "Manrope", sans-serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--foreground);
  --color-border: var(--border);
  --color-input: var(--border);
  --color-ring: var(--primary);
  --color-card: var(--background);
  --color-card-foreground: var(--foreground);
  --color-popover: var(--background);
  --color-popover-foreground: var(--foreground);
  --color-destructive: var(--destructive);
  --color-success: var(--success);
  --color-signal: var(--signal);
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-sm: 4px;
}

:root {
  --background: oklch(0.992 0.004 155);
  --foreground: oklch(0.21 0.024 160);
  --primary: oklch(0.88 0.205 123);
  --primary-foreground: oklch(0.2 0.03 150);
  --secondary: oklch(0.96 0.012 150);
  --muted: oklch(0.96 0.012 150);
  --muted-foreground: oklch(0.49 0.02 155);
  --accent: oklch(0.94 0.025 150);
  --border: oklch(0.89 0.014 150);
  --success: oklch(0.46 0.11 155);
  --signal: oklch(0.61 0.12 255);
  --destructive: oklch(0.58 0.2 28);
  --hero-surface: oklch(0.975 0.012 155);
  --ink: oklch(0.2 0.023 155);
  --ink-text: oklch(0.97 0.009 150);
  --ink-muted: oklch(0.68 0.027 155);
  --panel: oklch(0.26 0.024 155);
  --panel-border: oklch(0.35 0.025 155);
  --shadow-float: 0 12px 40px oklch(0.2 0.03 150 / 0.07);
}

.dark {
  --background: oklch(0.2 0.023 155);
  --foreground: oklch(0.97 0.009 150);
  --secondary: oklch(0.26 0.024 155);
  --muted: oklch(0.26 0.024 155);
  --muted-foreground: oklch(0.72 0.025 155);
  --accent: oklch(0.32 0.03 155);
  --border: oklch(0.35 0.025 155);
  --success: oklch(0.77 0.15 155);
  --hero-surface: oklch(0.23 0.025 155);
}

* {
  border-color: var(--border);
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  cursor: pointer;
}

.container-page {
  width: min(1140px, calc(100% - 80px));
  margin-inline: auto;
}

.navbar {
  height: 88px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 21px;
  font-weight: 750;
  text-decoration: none;
  color: var(--foreground);
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 32px;
  height: 36px;
}

.brand-mark svg {
  width: 32px;
  height: 36px;
}

.nav-links {
  display: flex;
  gap: 34px;
  align-items: center;
  font-size: 13px;
}

.nav-links a {
  text-decoration: none;
  color: var(--muted-foreground);
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--foreground);
}

.hero {
  position: relative;
  isolation: isolate;
  min-height: 650px;
  background: var(--hero-surface);
  overflow: hidden;
  border-bottom: 1px solid var(--border);
}

.hero-art {
  position: absolute;
  z-index: -1;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 62%;
}

.hero-content {
  text-align: center;
  padding-top: 49px;
  position: relative;
}

.eyebrow {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero .eyebrow {
  justify-content: center;
  font-size: 10px;
  margin-bottom: 23px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--success);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--success) 9%, transparent);
}

h1 {
  font-size: 68px;
  font-weight: 650;
  line-height: 1.12;
  margin: 0;
}

.highlight-word {
  position: relative;
  display: inline-block;
}

.highlight-word:after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 5px;
  bottom: 0;
  background: var(--primary);
  transform: rotate(-1deg);
}

.hero-copy {
  color: var(--muted-foreground);
  font-size: 16px;
  line-height: 1.7;
  margin: 24px auto 23px;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  gap: 13px;
  justify-content: center;
}

.hero-note {
  font-size: 11px;
  color: var(--muted-foreground);
  margin-top: 14px;
}

.activity-float {
  position: absolute;
  bottom: 31px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 15px 20px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--background);
  box-shadow: var(--shadow-float);
  min-width: 460px;
}

.activity-icon {
  background: var(--secondary);
  color: var(--success);
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 5px;
}

.activity-float p {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
}

.activity-float small {
  font-size: 10px;
  color: var(--muted-foreground);
}

.activity-float .lift {
  margin-left: auto;
  font-size: 13px;
  color: var(--success);
}

.integrations {
  text-align: center;
  padding: 35px 0 39px;
  border-bottom: 1px solid var(--border);
}

.integrations p {
  font-size: 11px;
  color: var(--muted-foreground);
  margin: 0 0 25px;
}

.integration-logos {
  display: flex;
  justify-content: center;
  gap: 65px;
  align-items: center;
}

.integration-logo {
  display: flex;
  align-items: center;
  gap: 7px;
  font-weight: 700;
  font-size: 21px;
}

.integration-logo svg {
  width: 24px;
  height: 24px;
}

.integration-logo.mixpanel {
  font-weight: 500;
}

.section {
  padding: 92px 0;
}

.section-heading {
  display: flex;
  justify-content: space-between;
  gap: 50px;
  align-items: end;
  margin-bottom: 46px;
}

.section-heading h2 {
  margin: 15px 0 0;
  font-size: 39px;
  line-height: 1.25;
  font-weight: 600;
}

.section-heading > p {
  color: var(--muted-foreground);
  font-size: 14px;
  line-height: 1.8;
  max-width: 305px;
  margin: 0 0 3px;
}

.workflow {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 66px;
  align-items: start;
}

.flow-step {
  display: flex;
  align-items: start;
  gap: 21px;
  width: 100%;
  padding: 20px 0;
  border-radius: 0;
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: normal;
  height: auto;
  justify-content: start;
  color: var(--muted-foreground);
}

.flow-step:hover {
  background: transparent;
  color: var(--foreground);
}

.flow-step.active {
  color: var(--foreground);
}

.step-number {
  font-family: monospace;
  font-size: 11px;
  padding-top: 5px;
  color: var(--muted-foreground);
}

.flow-step.active .step-number {
  color: var(--success);
}

.step-text strong {
  display: block;
  font-size: 17px;
  font-weight: 550;
}

.step-text p {
  font-size: 12px;
  line-height: 1.8;
  margin: 9px 0 0;
  font-weight: 400;
  color: var(--muted-foreground);
}

.step-arrow {
  margin-left: auto;
  margin-top: 4px;
  opacity: 0;
}

.active .step-arrow {
  opacity: 1;
}

.agent-panel {
  background: var(--ink);
  color: var(--ink-text);
  border-radius: 7px;
  overflow: hidden;
  min-height: 373px;
  box-shadow: var(--shadow-float);
}

.panel-top {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 17px 21px;
  border-bottom: 1px solid var(--panel-border);
  font-size: 11px;
}

.panel-top > span:last-child {
  margin-left: auto;
  color: var(--ink-muted);
  font-size: 9px;
}

.panel-content {
  padding: 26px;
}

.panel-eyebrow {
  color: var(--ink-muted);
  font-family: monospace;
  font-size: 10px;
}

.panel-content h3 {
  font-size: 22px;
  font-weight: 500;
  margin: 15px 0 8px;
}

.panel-content > p {
  color: var(--ink-muted);
  font-size: 12px;
  line-height: 1.8;
}

.event-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  padding: 15px 0;
  border-bottom: 1px solid var(--panel-border);
}

.event-row svg {
  color: var(--primary);
  width: 15px;
  height: 15px;
}

.event-row span:last-child {
  margin-left: auto;
  color: var(--ink-muted);
  font-size: 10px;
}

.panel-result {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 23px;
  font-size: 11px;
  color: var(--ink-muted);
}

.panel-result strong {
  color: var(--primary);
  font-size: 14px;
  font-weight: 500;
}

.loop-footnote {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin-top: 35px;
  font-size: 11px;
  color: var(--muted-foreground);
}

.safety-section {
  background: var(--secondary);
  border-block: 1px solid var(--border);
}

.safety-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 55px;
  margin-top: 40px;
}

.safety-item > svg {
  color: var(--success);
  width: 23px;
  height: 23px;
  margin-bottom: 15px;
}

.safety-item h3 {
  font-size: 17px;
  margin: 0 0 12px;
  font-weight: 600;
}

.safety-item p {
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.9;
  margin: 0;
}

.faq-layout {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 70px;
}

.faq-layout h2 {
  font-size: 36px;
  font-weight: 600;
  line-height: 1.25;
  margin: 16px 0 0;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-trigger {
  width: 100%;
  display: flex;
  justify-content: space-between;
  text-align: left;
  white-space: normal;
  padding: 22px 0;
  height: auto;
  border-radius: 0;
  font-size: 14px;
}

.faq-trigger:hover {
  background: transparent;
}

.faq-answer {
  margin: 0;
  padding: 0 35px 23px 0;
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.9;
}

.final-cta {
  text-align: center;
  padding: 70px 20px;
  background: var(--primary);
  color: var(--primary-foreground);
}

.final-cta h2 {
  font-size: 40px;
  line-height: 1.2;
  font-weight: 600;
  margin: 0 0 17px;
}

.final-cta p {
  font-size: 14px;
  margin-bottom: 27px;
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-block: 30px;
}

.footer .brand {
  font-size: 16px;
}

.footer > p {
  font-size: 11px;
  color: var(--muted-foreground);
}

.dialog-description {
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.8;
}

.demo-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 17px;
  gap: 10px;
}

.demo-controls > span {
  color: var(--muted-foreground);
  font-size: 11px;
}

.mobile-menu {
  display: none;
}

.dark .hero-art {
  opacity: 0.1;
}

@media (min-width: 1600px) {
  .hero-art {
    object-position: center 59%;
  }
}

@media (max-width: 800px) {
  .container-page {
    width: calc(100% - 40px);
  }

  .navbar {
    height: 75px;
  }

  .nav-links {
    gap: 20px;
  }

  .nav-links a {
    display: none;
  }

  h1 {
    font-size: 48px;
  }

  .hero {
    min-height: 650px;
  }

  .hero-content {
    padding-top: 58px;
  }

  .hero-copy {
    max-width: 450px;
    padding: 0 15px;
  }

  .integration-logos {
    gap: 30px;
    flex-wrap: wrap;
  }

  .integration-logo {
    font-size: 18px;
  }

  .section {
    padding: 65px 0;
  }

  .section-heading {
    gap: 25px;
  }

  .section-heading h2 {
    font-size: 32px;
  }

  .workflow {
    gap: 30px;
  }

  .safety-grid {
    gap: 25px;
  }

  .faq-layout {
    gap: 30px;
  }
}

@media (max-width: 600px) {
  .brand {
    font-size: 18px;
  }

  .navbar .nav-links > button {
    font-size: 11px;
    padding-inline: 12px;
  }

  h1 {
    font-size: 41px;
    line-height: 1.18;
  }

  .hero {
    min-height: 625px;
  }

  .hero-content {
    padding-top: 41px;
  }

  .hero .eyebrow {
    font-size: 9px;
  }

  .hero-copy {
    font-size: 14px;
    max-width: 340px;
  }

  .hero-art {
    object-position: center bottom;
  }

  .hero-actions {
    gap: 8px;
  }

  .hero-actions button {
    padding-inline: 16px;
    font-size: 12px;
  }

  .activity-float {
    min-width: 0;
    width: calc(100% - 40px);
    gap: 10px;
    padding: 13px;
    bottom: 24px;
  }

  .activity-float p {
    font-size: 11px;
  }

  .activity-float .lift {
    font-size: 11px;
  }

  .integrations {
    padding: 29px 0;
  }

  .integration-logos {
    gap: 24px;
  }

  .integration-logo {
    font-size: 16px;
  }

  .integration-logo svg {
    width: 19px;
  }

  .section-heading {
    display: block;
    margin-bottom: 23px;
  }

  .section-heading h2 {
    font-size: 31px;
  }

  .section-heading > p {
    margin-top: 20px;
  }

  .workflow {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .flow-step {
    padding: 17px 0;
  }

  .safety-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .safety-item {
    padding-left: 43px;
    position: relative;
  }

  .safety-item > svg {
    position: absolute;
    left: 0;
    top: 0;
  }

  .faq-layout {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .faq-layout h2 {
    font-size: 31px;
  }

  .final-cta h2 {
    font-size: 31px;
  }

  .footer {
    align-items: start;
    gap: 15px;
  }

  .footer > p {
    max-width: 125px;
    text-align: right;
    line-height: 1.7;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  * {
    animation: none !important;
    transition: none !important;
  }
}

import type { Metadata } from "next";
import { DM_Sans, Manrope } from "next/font/google";
import "./globals.css";

const dmSans = DM_Sans({
  subsets: ["latin"],
  variable: "--font-dm-sans",
});

const manrope = Manrope({
  subsets: ["latin"],
  variable: "--font-manrope",
});

export const metadata: Metadata = {
  title: "Friction Fixer — A website that gets better, by itself",
  description:
    "Meet the AI agent that finds visitor friction, improves your website, and measures what works.",
  openGraph: {
    title: "Friction Fixer",
    description:
      "Turn visitor behavior into better website experiences, automatically.",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
  },
  icons: {
    icon: { url: "/favicon.svg", type: "image/svg+xml" },
  },
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${dmSans.variable} ${manrope.variable}`}>
      <body>{children}</body>
    </html>
  );
}

import type { Metadata } from "next";
import { HomePage } from "@/components/home/home-page";

export const metadata: Metadata = {
  title: "Friction Fixer — Your website, better by itself",
  description:
    "An AI agent that finds what drives visitors away, fixes your website through GitHub, and keeps only the changes that work.",
  openGraph: {
    title: "Friction Fixer — Your website, better by itself",
    description:
      "Observe. Fix. Verify. Repeat. Turn your visitor analytics into a website that improves itself.",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
  },
};

export default function Page() {
  return <HomePage />;
}

"use client";

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  console.error(error);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="max-w-md text-center">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">
          This page didn&apos;t load
        </h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Something went wrong on our end. You can try refreshing or head back home.
        </p>
        <div className="mt-6 flex flex-wrap justify-center gap-2">
          <button
            onClick={() => reset()}
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Try again
          </button>
          <a
            href="/"
            className="inline-flex items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent"
          >
            Go home
          </a>
        </div>
      </div>
    </div>
  );
}

export function Brand() {
  return (
    <a className="brand" href="#" aria-label="Friction Fixer home">
      <span className="brand-mark" aria-hidden="true">
        <svg viewBox="0 0 40 40" fill="none">
          <path d="M12 4h23l-5 8H18l-4 7h16l-5 8H10L5 36 12 4Z" fill="currentColor" />
        </svg>
      </span>
      <span>
        friction fixer<span className="text-success">.</span>
      </span>
    </a>
  );
}

import { ArrowUpRight } from "lucide-react";
import { Brand } from "@/components/layout/brand";
import { Button } from "@/components/ui/button";

export function SiteHeader({ onOpenDemo }: { onOpenDemo: () => void }) {
  return (
    <header className="container-page navbar">
      <Brand />
      <nav className="nav-links" aria-label="Main navigation">
        <a href="#how-it-works">How it works</a>
        <a href="#built-for-you">Why Friction Fixer</a>
        <a href="#faq">FAQs</a>
        <Button variant="ink" onClick={onOpenDemo}>
          Meet your agent <ArrowUpRight />
        </Button>
      </nav>
    </header>
  );
}

import { Brand } from "@/components/layout/brand";

export function SiteFooter() {
  return (
    <footer className="container-page footer">
      <Brand />
      <p>© {new Date().getFullYear()} Friction Fixer. Always improving.</p>
    </footer>
  );
}

"use client";

import { useState } from "react";
import { ArrowRight, RotateCcw } from "lucide-react";
import { AgentPreview, steps } from "@/components/agent/agent-preview";
import { Button } from "@/components/ui/button";

export function WorkflowSection() {
  const [step, setStep] = useState(0);

  return (
    <section id="how-it-works" className="container-page section">
      <div className="section-heading">
        <div>
          <div className="eyebrow">
            <span className="text-success">01 —</span> THE FEEDBACK LOOP
          </div>
          <h2>
            From “why are they leaving?”
            <br />
            to “already fixed.”
          </h2>
        </div>
        <p>
          No more guessing, endless dashboards,
          <br className="hidden sm:block" /> or a backlog of “we should fix that.”
          <br className="hidden sm:block" /> Just a website that keeps getting better.
        </p>
      </div>
      <div className="workflow">
        <div role="tablist" aria-label="Agent workflow">
          {steps.map((item, i) => (
            <Button
              key={item.title}
              variant="ghost"
              className={`flow-step ${step === i ? "active" : ""}`}
              role="tab"
              aria-selected={step === i}
              aria-controls="workflow-preview"
              id={`step-${i}`}
              onClick={() => setStep(i)}
            >
