"use client";

import {
  cloneElement,
  isValidElement,
  type ButtonHTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react";
import "./button.css";

type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: "ink" | "hero" | "quiet" | "ghost";
  size?: "lg" | "default";
  asChild?: boolean;
};

function classes(variant: ButtonProps["variant"], size: ButtonProps["size"], className?: string) {
  return ["ui-button", variant && `ui-button-${variant}`, size === "lg" && "ui-button-lg", className]
    .filter(Boolean)
    .join(" ");
}

/** Placeholder. Swap this file for the real button when you have it. */
export function Button({ variant, size, asChild, className, children, ...props }: ButtonProps) {
  const buttonClass = classes(variant, size, className);

  if (asChild && isValidElement<{ className?: string }>(children)) {
    return cloneElement(children as ReactElement<{ className?: string }>, {
      className: [buttonClass, children.props.className].filter(Boolean).join(" "),
    });
  }

  return (
    <button type="button" className={buttonClass} {...props}>
      {children as ReactNode}
    </button>
  );
}

